const TZ = 'Asia/Manila';
return $input.all().filter((i) => i.json.kind).map(({ json: r }) => {
  const hi = 'Hi ' + (r.name ? r.name.split(' ')[0] : 'there') + ',';
  const sign = '\n\nBrightSmile Dental Clinic\n(032) 555-0142';
  const when = r.starts_at
    ? DateTime.fromISO(new Date(r.starts_at).toISOString()).setZone(TZ).setLocale('en-US').toFormat("ccc, LLL d 'at' h:mm a")
    : null;
  const emails = {
    nudge_24h: {
      subject: 'Still thinking about your ' + r.service + '?',
      body: hi + '\n\nThanks for chatting with us yesterday about your ' + r.service + '. We still have open slots this week. Reply to this email or chat with us on our website and we will book you in.' + sign,
    },
    nudge_72h: {
      subject: 'Your ' + r.service + ' at BrightSmile',
      body: hi + "\n\nThis is our last reminder about the " + r.service + " you asked about. Whenever you're ready, just reply to this email and we'll find a time that works for you." + sign,
    },
    appt_reminder: {
      subject: 'Reminder: your appointment tomorrow',
      body: hi + '\n\nA friendly reminder of your ' + r.service + ' on ' + when + '. If you need to reschedule, please reply to this email or call us.' + sign,
    },
  };
  return { json: { lead_id: r.lead_id, appointment_id: r.appointment_id ?? null, kind: r.kind, to: r.email, ...emails[r.kind] } };
});
